{
  "title": "Methane Release Investigation - Compressor K-201 Discharge Area (XV-2104/F-205)",
  "observed_evidence": [
    {
      "statement": "61 methane episodes Sep 6–Oct 23; 54/61 start within 90 min of K-201 load changes; clustering at 06:00 and 17:00–18:00 UTC.",
      "evidence_ids": ["history:HIST-FAC-001:2026-09-06:2026-10-23T19:55:00+00:00", "operations:K-201:load-change-log"]
    },
    {
      "statement": "WO-008 OGI during 06:00 load change showed faint intermittent plume at XV-2104 stem packing; no plume at steady load. F-205 flange showed no indication.",
      "evidence_ids": ["field_report:FR-008", "maintenance:WO-008"]
    },
    {
      "statement": "WO-009 re-torqued XV-2104 gland follower to 35 N·m; soap test at steady load negative. WO-008-C2 repeat OGI during load change not done.",
      "evidence_ids": ["field_report:FR-009", "commitment:WO-008-C2"]
    },
    {
      "statement": "F-205 gasket replaced WO-004 but torque verification (WO-004-C1) missing; no OGI survey of F-205 during load change after replacement.",
      "evidence_ids": ["field_report:FR-004", "maintenance:WO-004", "commitment:WO-004-C1"]
    },
    {
      "statement": "Incident day: CH4 sensors at XV-2104 rise 2→56 ppm, pressure 12.5→14.0 bar(a) during 20:09 load change; QOGI estimates 1.06 kg/h but wind missing, attribution unassessed.",
      "evidence_ids": ["measurements:SCN-003:685:300", "operations:K-201:load-change-log", "calculation:INC-003-M001:685:XV-2104"]
    }
  ],
  "hypotheses": [
    {
      "statement": "XV-2104 stem packing leak is load-dependent; re-torque at steady load did not address dynamic sealing under pressure transients.",
      "evidence_ids": ["field_report:FR-008", "field_report:FR-009", "document:DS-XV-2104#complete_example", "measurements:SCN-003:685:300"]
    },
    {
      "statement": "F-205 flange gasket may leak under load changes; torque verification missing and no load-change OGI performed post-replacement.",
      "evidence_ids": ["field_report:FR-004", "commitment:WO-004-C1", "history:HIST-FAC-001:2026-09-06:2026-10-23T19:55:00+00:00"]
    },
    {
      "statement": "Hissing reported during 17:30 load change (WO-012) could originate from either XV-2104 packing or F-205 flange; proximity and shared camera overlap prevent separation.",
      "evidence_ids": ["field_report:FR-012", "camera:CAM-02/region/XV-2104", "camera:CAM-02/region/F-205"]
    }
  ],
  "recommended_checks": [
    {
      "statement": "Complete WO-004-C1: obtain or repeat F-205 bolt torque verification per DS-F-205 before any packing work.",
      "evidence_ids": ["commitment:WO-004-C1", "document:PROC-002#complete_example"]
    },
    {
      "statement": "Schedule and perform WO-008-C2: repeat OGI survey of XV-2104 during a K-201 load change as first field check (priority high).",
      "evidence_ids": ["commitment:WO-008-C2", "document:PROC-003#complete_example"]
    },
    {
      "statement": "Conduct engineering review per WO-012 to distinguish XV-2104 packing vs F-205 flange using hissing report, sensor data, and load-change alignment.",
      "evidence_ids": ["maintenance:WO-012", "field_report:FR-012", "measurements:SCN-003:685:300"]
    },
    {
      "statement": "Verify weather mast MET-01 operation; restore wind data for plume attribution and Gaussian/bLs/CFD methods.",
      "evidence_ids": ["measurements:SCN-003:685:300", "calculation:INC-003-M001:685:XV-2104"]
    },
    {
      "statement": "Calibrate CAM-02 equipment mapping; current overlap fractions (XV-2104 61.5%, F-205 53.8%) are illustrative only.",
      "evidence_ids": ["camera:CAM-02/region/XV-2104", "camera:CAM-02/region/F-205", "document:PROC-001#complete_example"]
    }
  ],
  "unresolved_questions": [
    "Was F-205 bolt torque verification (WO-004-C1) completed after Aug 19 gasket replacement?",
    "Will repeat OGI of XV-2104 during load change (WO-008-C2) be scheduled and performed?",
    "Can engineering review (WO-012-C1) distinguish XV-2104 packing from F-205 flange given hissing, sensor data, and load-change alignment?",
    "Why did weather mast stop at scenario 600s on incident day, and was 20:09:45 UTC load change the trigger for methane/pressure rise?"
  ],
  "safety_prerequisites": [
    "Isolate and depressurize per approved site procedure before any packing or flange work (PROC-002).",
    "Verify LOTO and permit requirements for XV-2104 and F-205 on line L-201 (PID-001).",
    "Confirm gas detection and fire watch during any live-load OGI survey near compressor discharge.",
    "Use manufacturer-approved torque values and procedures for XV-2104 gland follower (DS-XV-2104) and F-205 flange."
  ]
}
